using System;using System.Collections.Generic;
namespace Igor.WorksitesRussian{public static class WorksiteAttackerNames{
private static readonly Dictionary<string,string[]> Prefixes=new Dictionary<string,string[]>{{"The Concerned",new[]{"Обеспокоенный","Обеспокоенная","Обеспокоенное","Обеспокоенные"}},{"The Contracted",new[]{"Контрактный","Контрактная","Контрактное","Контрактные"}},{"The Righteous",new[]{"Праведный","Праведная","Праведное","Праведные"}},{"The Hired",new[]{"Наёмный","Наёмная","Наёмное","Наёмные"}},{"The Citizens'",new[]{"Гражданский","Гражданская","Гражданское","Гражданские"}},{"The People's",new[]{"Народный","Народная","Народное","Народные"}},{"The Pacifist",new[]{"Миролюбивый","Миролюбивая","Миролюбивое","Миролюбивые"}},{"The Drunken",new[]{"Пьяный","Пьяная","Пьяное","Пьяные"}},{"The Friendly",new[]{"Дружелюбный","Дружелюбная","Дружелюбное","Дружелюбные"}},{"The Dust-Munching",new[]{"Жующий пыль","Жующая пыль","Жующее пыль","Жующие пыль"}},{"The Starving",new[]{"Изголодавшийся","Изголодавшаяся","Изголодавшееся","Изголодавшиеся"}},{"The Hungry",new[]{"Голодный","Голодная","Голодное","Голодные"}}};
private static readonly Dictionary<string,Tuple<string,int>> Suffixes=new Dictionary<string,Tuple<string,int>>{{"Vigilantes",Tuple.Create("дружинники",3)},{"Militia",Tuple.Create("ополчение",2)},{"Coalition",Tuple.Create("коалиция",1)},{"Mercenaries",Tuple.Create("наёмники",3)},{"Posse",Tuple.Create("дружина",1)},{"Enforcers",Tuple.Create("каратели",3)},{"Marauders",Tuple.Create("мародёры",3)},{"Moochers",Tuple.Create("нахлебники",3)},{"Chancers",Tuple.Create("авантюристы",3)},{"Raiders",Tuple.Create("налётчики",3)},{"Bandits",Tuple.Create("бандиты",3)},{"Pirates",Tuple.Create("пираты",3)},{"Kill Squad",Tuple.Create("отряд убийц",0)},{"Soup Gang",Tuple.Create("суповая шайка",1)}};
private static readonly Dictionary<string,string> Labels=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"a vigilante militia","ополчение дружинников"},{"a band of armed vigilantes","вооружённая дружина"},{"a squad of enforcers","отряд карателей"},{"a posse of local vigilantes","дружина местных жителей"},{"a pirate warband","пиратская ватага"},{"a pirate raiding party","рейдовый отряд пиратов"},{"a pirate crew","команда пиратов"},{"a middling pirate gang","заурядная пиратская банда"}};
public static string Name(string prefix,string separator,string suffix){if(separator==" "&&Prefixes.TryGetValue(prefix,out var forms)&&Suffixes.TryGetValue(suffix,out var noun))return forms[noun.Item2]+" "+noun.Item1;return string.Concat(prefix,separator,suffix);}
public static string Label(string source)=>source!=null&&Labels.TryGetValue(source,out var russian)?russian:source;
}}
